std::string Read(const fs::path& path){std::ifstream in(path,std::ios::binary);Need(in.good(),"Scene move fixture read failed");return {std::istreambuf_iterator<char>(in),std::istreambuf_iterator<char>()};}
Assets::AssetImportJob::Result Wait(Assets::AssetImportJob& job){Assets::AssetImportJob::Result result;const auto until=std::chrono::steady_clock::now()+std::chrono::seconds(15);while(!job.Poll(result)){Need(std::chrono::steady_clock::now()<until,"Scene asset worker timeout");std::this_thread::sleep_for(std::chrono::milliseconds(1));}return result;}
